// ── Константы для часто повторяющихся строк ─────────────────
const _ASI  = "+2 к одной характеристике или +1 к двум. Либо черта PHB.";
const _FEAT = function() { return {name:"Увеличение характеристик", desc:_ASI}; };

function escapeHtml(text) {
  if (text === null || text === undefined) return "";
  return String(text)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

// AUD-1 (S1): src аватара из данных пользователя — только base64-картинка или https, иначе "".
function safeImageSrc(src) {
  if (typeof src !== "string") return "";
  if (/^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+\/=]+$/.test(src)) return src;
  if (/^https:\/\/[^\s"'<>\\]+$/i.test(src)) return src;
  return "";
}

