// ── Шаблон записи-карточки notesV2 (entry) ────────────────────────────────────
// type: 'npc' | 'quest' | 'location' | 'session' | 'hook' | 'free'
function createEntry(type) {
  var now = Date.now();
  return {
    id: 'e' + now + '_' + Math.random().toString(36).slice(2, 8),
    type: type || 'free',
    title: '',
    body: '',
    tags: [],
    pinned: false,
    createdAt: now,
    updatedAt: now
  };
}

