// Авторство стороннего подкласса: подпись в UI вместо общей метки источника.
const SUBCLASS_CREDIT = {
  "Путь живого оружия": { short: "авторский · Exploring Eberron, Кит Бейкер", full: "Exploring Eberron, Кит Бейкер (DMs Guild) — неофициальный материал" }
};
// Короткая метка источника для UI («PHB» / «XGtE» / «авторский»…). "" если неизвестен.
// E24-7: char необязателен — с ним источник берётся из таблицы редакции персонажа.
function subclassSourceShort(name, char) {
  if (SUBCLASS_CREDIT[name]) return SUBCLASS_CREDIT[name].short;
  var code = (char ? edData(char).SUBCLASS_SOURCE : SUBCLASS_SOURCE)[name];
  return (code && SOURCE_LABELS[code]) ? SOURCE_LABELS[code].short : "";
}
// Полное имя книги-источника (для title/тултипа).
function subclassSourceFull(name, char) {
  if (SUBCLASS_CREDIT[name]) return SUBCLASS_CREDIT[name].full;
  var code = (char ? edData(char).SUBCLASS_SOURCE : SUBCLASS_SOURCE)[name];
  return (code && SOURCE_LABELS[code]) ? SOURCE_LABELS[code].full : "";
}
// ED-4: книги-дополнения персонажа. char.books — включённые коды; PHB/PH24 всегда.
// Нет массива (или нет персонажа) — доступно всё.
// DOP-3: все коды реестра, кроме PHB/PH24.
const BOOK_CODES = Object.keys(SOURCE_LABELS).filter(function(c) { return c !== "PHB" && c !== "PH24"; });
// DOP-3: глобально выключенные книги — ключ dnd_books, JSON-массив выключенных кодов
// (книга, которой нет в списке, включена). Пересекается с char.books в charHasBook.
var _booksOffCache = null;
function booksOff() {
  if (_booksOffCache) return _booksOffCache;
  var v = null;
  try { v = JSON.parse(localStorage.getItem("dnd_books") || "[]"); } catch (e) {}
  _booksOffCache = Array.isArray(v) ? v : [];
  return _booksOffCache;
}
function setBooksOff(list) {
  _booksOffCache = list.slice();
  try { localStorage.setItem("dnd_books", JSON.stringify(_booksOffCache)); } catch (e) {}
}
function bookGloballyOn(code) {
  return !code || code === "PHB" || code === "PH24" || booksOff().indexOf(code) === -1;
}
// Коды книг, у которых в данных есть расы, подклассы или предыстории: только их показывает UI.
function booksWithContent() {
  var has = {};
  Object.keys(SUBCLASS_SOURCE).forEach(function(k) { has[SUBCLASS_SOURCE[k]] = true; });
  Object.keys(RACE_DATA).forEach(function(k) { if (RACE_DATA[k].source) has[RACE_DATA[k].source] = true; });
  Object.keys(BACKGROUND_SKILLS).forEach(function(k) { if (BACKGROUND_SKILLS[k].source) has[BACKGROUND_SKILLS[k].source] = true; });
  return BOOK_CODES.filter(function(c) { return has[c]; });
}
function charHasBook(char, code) {
  if (!code || code === "PHB" || code === "PH24") return true;
  if (!bookGloballyOn(code)) return false;
  if (!char || !Array.isArray(char.books)) return true;
  return char.books.indexOf(code) !== -1;
}
// HB-8: запись своего подкласса; битое отбрасываем, лишние поля не тащим.
function customSubclassesClean(list) {
  if (!Array.isArray(list)) return [];
  return list.filter(function(s) {
    return s && typeof s.name === "string" && s.name.trim() && typeof s.cls === "string" && s.cls;
  }).map(function(s) {
    var feats = Array.isArray(s.features) ? s.features : [];
    return { name: s.name.trim(), cls: s.cls, homebrew: true,
      features: feats.filter(function(f) {
        var lv = f ? parseInt(f.level, 10) : 0;
        return f && typeof f.name === "string" && f.name.trim() && lv >= 1 && lv <= 20;
      }).map(function(f) {
        return { level: parseInt(f.level, 10) || 0, name: f.name.trim(), desc: String(f.desc || "") };
      }) };
  });
}
function isCustomSubclass(name, char) {
  return !!char && Array.isArray(char.customSubclasses) && char.customSubclasses.some(function(s) { return s && s.name === name; });
}
function subclassInBooks(name, char) {
  if (isCustomSubclass(name, char)) return true;  // HB-8: метка HB, но выключатель книг к нему не относится
  return charHasBook(char, (char ? edData(char).SUBCLASS_SOURCE : SUBCLASS_SOURCE)[name]);
}
// Классы из дополнений: у них есть книга-источник, и они только в редакции 2014.
const CLASS_SOURCE = { "Изобретатель": "TCoE" };
function classInBooks(cls, char) {
  var code = CLASS_SOURCE[cls];
  if (!code) return true;
  if (char && char.edition === "2024") return false;
  return charHasBook(char, code);
}
if (typeof window !== "undefined") {
  window.SUBCLASS_SOURCE = SUBCLASS_SOURCE;
  window.SOURCE_LABELS = SOURCE_LABELS;
  window.subclassSourceShort = subclassSourceShort;
  window.subclassSourceFull = subclassSourceFull;
}

