// effects: массив авто-применяемых изменений при выборе черты
//   { type: "stat", key: "str", value: 1 }               — +1 к характеристике
//   { type: "stat_choice", keys: [...], value: 1 }        — +1 к одной из характеристик (авто: первая <20)
//   { type: "stat_choice_save", keys: [...], value: 1 }   — то же + владение спасброском этой хар-ки
//   { type: "armor", value: "light|medium|heavy|shield" } — владение бронёй (источник «черта» в recalcArmorWeaponFromSources)
//   { type: "hp_per_level", value: 2 }                    — +N ХП на каждый уровень (ретроактивно)
//   { type: "hp_flat", value: 40 }                        — +N к максимуму ХП один раз
//   { type: "initiative_bonus", value: 5 }                — бонус к инициативе (char.bonuses.initiative, читает вкладка «Бой»)
//   { type: "initiative_prof" }                           — БМ к инициативе (char.bonuses.initiativeProf; «Бдительный» 2024, E24-3)
//   { type: "weapon", value: "simple|martial" }           — владение категорией оружия (источник «черта»; E24-3)
//   { type: "passive" }                                   — только описание, нет авто-механики
//   у stat/stat_choice: max — потолок характеристики (по умолчанию 20; эпические дары 2024 — 30)
// Применители эффектов: applyASI (app-asi.js) и luApplyFeatById (app-hp.js) — новые типы добавлять В ОБА
